import whisper
import json
import re

# Single filler words to detect
SINGLE_FILLERS = {
    "um", "uh", "hum", "hmm", "mhm",
    "like", "yeah", "so", "basically", "well", "okay"
}

# Multi-word phrases to detect
PHRASE_FILLERS = ["you know", "i mean", "kind of", "i guess"]

def transcribe_audio(audio_path):
    """Transcribe audio with word-level timestamps."""
    print("Loading whisper model...")
    model = whisper.load_model("tiny")

    print("Transcribing audio...")
    result = model.transcribe(audio_path, word_timestamps=True, language="en")

    words = []
    for segment in result["segments"]:
        if "words" in segment:
            for word_info in segment["words"]:
                words.append({
                    "word": word_info["word"].strip(),
                    "start": word_info["start"],
                    "end": word_info["end"]
                })

    return words

def find_single_fillers(transcription):
    """Find single filler words."""
    matches = []

    for item in transcription:
        word = item["word"].lower().strip()
        # Remove punctuation for matching
        clean_word = re.sub(r'[^\w]', '', word)

        if clean_word in SINGLE_FILLERS:
            matches.append({
                "word": clean_word,
                "timestamp": round(item["start"], 2),
                "end": round(item["end"], 2)
            })

    return matches

def find_phrase_fillers(transcription):
    """Find multi-word phrase fillers."""
    matches = []

    # Clean words for matching
    words_clean = []
    for item in transcription:
        clean = re.sub(r'[^\w]', '', item["word"].lower().strip())
        words_clean.append(clean)

    for phrase in PHRASE_FILLERS:
        phrase_words = phrase.split()
        phrase_len = len(phrase_words)

        for i in range(len(words_clean) - phrase_len + 1):
            if words_clean[i:i+phrase_len] == phrase_words:
                matches.append({
                    "word": phrase,
                    "timestamp": round(transcription[i]["start"], 2),
                    "end": round(transcription[i + phrase_len - 1]["end"], 2)
                })

    return matches

def detect_fillers(audio_path, output_path):
    """Main function to detect all filler words and save to JSON."""
    # Transcribe
    transcription = transcribe_audio(audio_path)

    print(f"Transcribed {len(transcription)} words")

    # Find fillers
    single_matches = find_single_fillers(transcription)
    phrase_matches = find_phrase_fillers(transcription)

    # Combine and sort by timestamp
    all_matches = single_matches + phrase_matches
    all_matches.sort(key=lambda x: x["timestamp"])

    # Format output (keep word and timestamp, store end separately for video editing)
    output = []
    for match in all_matches:
        output.append({
            "word": match["word"],
            "timestamp": match["timestamp"],
            "end": match["end"]
        })

    with open(output_path, "w") as f:
        json.dump(output, f, indent=2)

    print(f"Found {len(output)} filler words/phrases")
    for item in output:
        print(f"  {item['word']}: {item['timestamp']}s - {item['end']}s")

    return output

if __name__ == "__main__":
    detect_fillers("/root/input.mp4", "/root/annotations.json")

